/// What plays behind the Now Playing screen.
///
/// Each scene is a short muted loop bundled under assets/videos/backgrounds/,
/// with a poster frame of the same name. Both are generated by
/// tools/generate_backgrounds/generate.py.
enum PlayerBackdrop {
  none,
  flame,
  rain,
  wind,
  forest,
  sea;

  bool get hasVideo => this != none;

  String get video => 'assets/videos/backgrounds/$name.mp4';

  /// A still from the loop: the picker thumbnail, and what is shown instead
  /// of the video when the system asks for reduced motion.
  String get poster => 'assets/videos/backgrounds/$name.jpg';

  /// Unknown or missing names (older builds, cleared storage) fall back to
  /// [none].
  static PlayerBackdrop fromName(String? name) {
    for (final b in values) {
      if (b.name == name) return b;
    }
    return none;
  }
}
